import React, { useEffect, useMemo, useState } from "react";
import Header from "../components/Header";
import UrlInput from "../components/UrlInput";
import ChatAI from "../components/ChatAI";
import History from "../components/History";
import Loader from "../components/Loader";
import MindMap from "../components/MindMap";
import {
  summarizeText,
  summarizeUrl,
  summarizeVideo,
  summarizeAudio,
  summarizeDocument,
  summarizeImage,
  askArticleChat,
  getHistory,
  deleteHistoryItem
} from "../services/api";

function Home() {
  const [mode, setMode] = useState("webpage");
  const [url, setUrl] = useState("");
  const [text, setText] = useState("");
  const [videoFile, setVideoFile] = useState(null);
  const [audioFile, setAudioFile] = useState(null);
  const [documentFile, setDocumentFile] = useState(null);
  const [imageFile, setImageFile] = useState(null);
  const [language, setLanguage] = useState("English");
  const [result, setResult] = useState({
    summary: "",
    keyPoints: [],
    markdownSummary: "",
    description: "",
    extractedText: "",
    imagePreview: "",
    title: "",
    sourceUrl: "",
    originalText: "",
    source: "",
    transcriptionNote: ""
  });
  const [summaryId, setSummaryId] = useState("");
  const [history, setHistory] = useState([]);
  const [messages, setMessages] = useState([]);
  const [loading, setLoading] = useState(false);
  const [chatLoading, setChatLoading] = useState(false);
  const [retryVisionLoading, setRetryVisionLoading] = useState(false);
  const [error, setError] = useState("");
  const [activeTab, setActiveTab] = useState("summary");

  const getFriendlyErrorMessage = (requestError, fallbackMessage) => {
    const message = String(requestError?.response?.data?.error || "").toLowerCase();

    if (message.includes("quota") || message.includes("billing") || message.includes("insufficient_quota")) {
      return "Your OpenAI key needs active billing and available quota.";
    }

    return requestError?.response?.data?.error || fallbackMessage;
  };

  const applySummaryResult = (data, currentMode, selectedImageFile) => {
    const imagePreview = currentMode === "image" && selectedImageFile ? URL.createObjectURL(selectedImageFile) : "";

    setResult({
      summary: data.summary || "",
      keyPoints: data.keyPoints || [],
      markdownSummary: data.markdownSummary || "",
      description: data.description || "",
      extractedText: data.extractedText || "",
      imagePreview,
      title: data.title || "",
      sourceUrl: data.sourceUrl || "",
      source: data.source || "",
      transcriptionNote: data.transcriptionNote || "",
      originalText:
        currentMode === "text"
          ? text
          : data.originalText || data.extractedText || data.description || ""
    });
    setSummaryId(data.summaryId || "");
    setMessages([]);
    setActiveTab("summary");
  };

  const refreshHistory = async () => {
    try {
      const data = await getHistory();
      setHistory(data || []);
    } catch (_error) {
      setHistory([]);
    }
  };

  useEffect(() => {
    refreshHistory();
  }, []);

  useEffect(() => {
    const searchParams = new URLSearchParams(window.location.search);
    const tool = (searchParams.get("tool") || "").toLowerCase();

    const toolModeMap = {
      ppt: "pdf",
      image: "image",
      word: "pdf",
      book: "text"
    };

    if (toolModeMap[tool]) {
      setMode(toolModeMap[tool]);
      setError("");
      window.scrollTo({ top: 0, behavior: "smooth" });
    }
  }, []);

  const handleGenerate = async () => {
    setError("");
    setLoading(true);

    // Check for unsupported modes
    if (mode === "video" && !videoFile) {
      setError("Please upload a video file first.");
      setLoading(false);
      return;
    }

    if (mode === "audio" && !audioFile) {
      setError("Please upload an audio file first.");
      setLoading(false);
      return;
    }

    if (mode === "pdf" && !documentFile) {
      setError("Please upload a document file first.");
      setLoading(false);
      return;
    }

    if (mode === "image" && !imageFile) {
      setError("Please upload an image file first.");
      setLoading(false);
      return;
    }

    try {
      // Handle YouTube and Webpage as URL inputs
      const inputUrl = mode === "youtube" || mode === "webpage" ? url : null;
      const inputText = mode === "text" ? text : null;

      let data;
      if (mode === "video") {
        data = await summarizeVideo({ file: videoFile, language });
      } else if (mode === "audio") {
        data = await summarizeAudio({ file: audioFile, language });
      } else if (mode === "pdf") {
        data = await summarizeDocument({ file: documentFile, language });
      } else if (mode === "image") {
        data = await summarizeImage({ file: imageFile, language });
      } else {
        data =
          inputUrl
            ? await summarizeUrl({ url: inputUrl, language })
            : await summarizeText({ text: inputText, language });
      }

      applySummaryResult(data, mode, imageFile);
      if (mode === "video") {
        setVideoFile(null);
      }
      if (mode === "audio") {
        setAudioFile(null);
      }
      if (mode === "pdf") {
        setDocumentFile(null);
      }
      await refreshHistory();
    } catch (requestError) {
      setError(getFriendlyErrorMessage(requestError, "Failed to generate summary."));
    } finally {
      setLoading(false);
    }
  };

  const handleRetryVision = async () => {
    if (!imageFile) {
      setError("To retry vision, upload the image again and click Generate Summary.");
      return;
    }

    setError("");
    setRetryVisionLoading(true);

    try {
      const data = await summarizeImage({ file: imageFile, language });
      applySummaryResult(data, "image", imageFile);
      await refreshHistory();
    } catch (requestError) {
      setError(getFriendlyErrorMessage(requestError, "Vision retry failed. Please try again."));
    } finally {
      setRetryVisionLoading(false);
    }
  };

  const handleFallbackChatPrompt = async (prompt) => {
    if (!canChat || chatLoading) {
      return;
    }

    setActiveTab("chat");
    await handleAsk(prompt);
  };

  const handleAsk = async (question) => {
    setChatLoading(true);

    try {
      const response = await askArticleChat({
        question,
        summaryId,
        contextText: result.originalText || result.summary,
        language
      });

      const answer = response.answer || "No answer generated.";
      setMessages((prev) => [...prev, { id: crypto.randomUUID(), question, answer }]);
      setActiveTab("chat");
    } catch (requestError) {
      setMessages((prev) => [
        ...prev,
        {
          id: crypto.randomUUID(),
          question,
          answer: getFriendlyErrorMessage(requestError, "Unable to answer right now.")
        }
      ]);
      setActiveTab("chat");
    } finally {
      setChatLoading(false);
    }
  };

  const loadHistoryItem = (item) => {
    setResult({
      summary: item.summaryText || "",
      keyPoints: item.keyPoints || [],
      markdownSummary: item.markdownSummary || "",
      description: item.description || "",
      extractedText: item.extractedText || "",
      imagePreview: "",
      title: item.title || "",
      sourceUrl: item.sourceUrl || "",
      originalText: item.originalText || "",
      source: "",
      transcriptionNote: item.transcriptionNote || ""
    });
    setSummaryId(item._id || "");
    
    // Determine mode from sourceUrl or sourceType
    let newMode = "text";
    if (item.sourceType === "video") {
      newMode = "video";
    } else if (item.sourceType === "audio") {
      newMode = "audio";
    } else if (item.sourceType === "image") {
      newMode = "image";
    } else if (item.sourceType === "document") {
      newMode = "pdf";
    } else if (item.sourceType === "url") {
      // Check if it's a YouTube URL
      if (item.sourceUrl && (item.sourceUrl.includes("youtube.com") || item.sourceUrl.includes("youtu.be"))) {
        newMode = "youtube";
      } else {
        newMode = "webpage";
      }
    }
    
    setMode(newMode);
    setText(item.originalText || "");
    setUrl(item.sourceUrl || "");
    setVideoFile(null);
    setAudioFile(null);
    setDocumentFile(null);
    setImageFile(null);
    setLanguage(item.language || "English");
    setMessages([]);
    setActiveTab("summary");
  };

  const removeHistory = async (id) => {
    try {
      await deleteHistoryItem(id);
      await refreshHistory();
    } catch (_error) {
      setError("Failed to delete history item.");
    }
  };

  const canChat = useMemo(() => Boolean(result.summary), [result.summary]);
  const hasSummary = useMemo(() => Boolean(result.summary), [result.summary]);

  const tabs = [
    { id: "summary", label: "Summary", icon: "📋" },
    { id: "keypoints", label: "Key Points", icon: "⭐" },
    { id: "mindmap", label: "Mind Map", icon: "🧠" },
    { id: "chat", label: "AI Chat", icon: "💬" }
  ];

  return (
    <main className="min-h-screen bg-[radial-gradient(circle_at_top,#042f2e,#020617_55%,#020617)] px-4 py-6 text-white sm:px-6">
      <div className="mx-auto max-w-full space-y-6">
        <Header />

        <UrlInput
          mode={mode}
          setMode={setMode}
          url={url}
          setUrl={setUrl}
          text={text}
          setText={setText}
          videoFile={videoFile}
          setVideoFile={setVideoFile}
          audioFile={audioFile}
          setAudioFile={setAudioFile}
          documentFile={documentFile}
          setDocumentFile={setDocumentFile}
          imageFile={imageFile}
          setImageFile={setImageFile}
          language={language}
          setLanguage={setLanguage}
          onGenerate={handleGenerate}
          loading={loading}
        />

        {loading ? <Loader label="Generating summary, key points, and markdown..." /> : null}

        {error ? (
          <div className="rounded-2xl border border-rose-400/50 bg-rose-900/40 px-4 py-3 text-sm text-rose-100">
            {error}
          </div>
        ) : null}

        {hasSummary ? (
          <div className="grid grid-cols-1 gap-4 lg:grid-cols-4">
            <div className="lg:col-span-2 rounded-3xl bg-slate-900/80 p-5 ring-1 ring-cyan-300/20">
              <h2 className="mb-3 text-xl font-extrabold text-cyan-100">📄 Full Article</h2>
              {result.imagePreview ? (
                <div className="mb-3 overflow-hidden rounded-2xl ring-1 ring-cyan-400/30">
                  <img src={result.imagePreview} alt="Uploaded preview" className="h-52 w-full object-cover" />
                </div>
              ) : null}
              <div className="max-h-[70vh] overflow-y-auto rounded-2xl bg-slate-950/70 p-4 text-sm leading-6 text-cyan-50">
                <p>{result.originalText || "No article content."}</p>
              </div>

              <div className="mt-3 flex items-center gap-2 text-xs text-cyan-300">
                <span className="font-semibold">{result.title}</span>
                {result.sourceUrl && (
                  <a href={result.sourceUrl} target="_blank" rel="noopener noreferrer" className="text-cyan-400 hover:underline">
                    (Open original)
                  </a>
                )}
              </div>
            </div>

            <div className="lg:col-span-2 rounded-3xl bg-slate-900/80 p-5 ring-1 ring-cyan-300/20">
              <div className="mb-4 flex flex-wrap gap-1 rounded-xl bg-slate-950/70 p-2">
                {tabs.map((tab) => (
                  <button
                    key={tab.id}
                    onClick={() => setActiveTab(tab.id)}
                    className={`flex items-center gap-1 rounded-lg px-3 py-2 text-sm font-semibold transition ${
                      activeTab === tab.id
                        ? "bg-cyan-400 text-slate-950"
                        : "bg-slate-800 text-cyan-100 hover:bg-slate-700"
                    }`}
                  >
                    <span>{tab.icon}</span>
                    <span className="hidden sm:inline">{tab.label}</span>
                  </button>
                ))}
              </div>

              <div className="max-h-[65vh] overflow-y-auto rounded-2xl bg-slate-950/70 p-4">
                {activeTab === "summary" && (
                  <div className="space-y-3">
                    <h3 className="text-lg font-bold text-cyan-100">Summary</h3>
                    {result.transcriptionNote ? (
                      <div className="rounded-lg border border-amber-300/40 bg-amber-900/20 p-3 text-xs text-amber-100">
                        {result.transcriptionNote}
                      </div>
                    ) : null}
                    {result.source === "fallback+ocr" ? (
                      <div className="rounded-lg border border-amber-300/40 bg-amber-900/20 p-3 text-xs text-amber-100">
                        <p className="mb-2">
                          <span className="font-semibold">OCR Mode Active:</span> AI Vision is temporarily unavailable. Local text extraction generated this summary.
                        </p>

                        {result.extractedText && (
                          <div className="mb-3 rounded-md border border-amber-200/30 bg-slate-900/40 p-3">
                            <p className="mb-2 text-[11px] font-semibold text-amber-50">📋 Extracted Text (OCR)</p>
                            <p className="whitespace-pre-wrap text-[10px] leading-4 text-amber-100">
                              {result.extractedText.slice(0, 500)}
                              {result.extractedText.length > 500 ? "..." : ""}
                            </p>
                          </div>
                        )}

                        <div className="mt-3 flex flex-wrap items-center gap-2">
                          <button
                            type="button"
                            onClick={handleRetryVision}
                            disabled={retryVisionLoading || loading || !imageFile}
                            className="rounded-md bg-amber-300 px-3 py-1.5 text-xs font-semibold text-slate-900 disabled:cursor-not-allowed disabled:opacity-60"
                          >
                            {retryVisionLoading ? "Retrying Vision..." : "🔄 Retry Vision"}
                          </button>
                          {!imageFile ? (
                            <span className="text-[11px] text-amber-200">
                              Re-upload the image to retry Vision on this result.
                            </span>
                          ) : null}
                        </div>

                        <div className="mt-3 rounded-md border border-amber-200/30 bg-amber-950/30 p-3 text-[11px] leading-5 text-amber-100">
                          <p className="mb-2 font-semibold text-amber-50">📸 Next steps to recover Vision API</p>
                          <ul className="mt-1 list-disc space-y-0.5 pl-4">
                            <li>Retry Vision first. Temporary outages often recover quickly.</li>
                            <li>Reduce glare and increase contrast so labels on metallic parts are readable.</li>
                            <li>Capture a tighter crop around product names and model markings.</li>
                          </ul>
                        </div>

                        <div className="mt-3 rounded-md border border-cyan-300/30 bg-cyan-950/20 p-3 text-[11px] leading-5 text-cyan-100">
                          <p className="font-semibold text-cyan-50">Ask AI for a second, deeper pass</p>
                          <p className="mt-1">
                            Use AI Chat prompts to extract product and hardware details from OCR text and context.
                          </p>
                          <div className="mt-2 flex flex-wrap gap-2">
                            <button
                              type="button"
                              onClick={() =>
                                handleFallbackChatPrompt(
                                  "What are the specifications of the Climax 'K' sticks shown in this image?"
                                )
                              }
                              disabled={chatLoading || !canChat}
                              className="rounded-md bg-cyan-300 px-3 py-1.5 font-semibold text-slate-900 disabled:cursor-not-allowed disabled:opacity-60"
                            >
                              Ask About K Sticks
                            </button>
                            <button
                              type="button"
                              onClick={() =>
                                handleFallbackChatPrompt(
                                  "Identify likely product, form factor, quantity, and any visible valve or fitting components from this result."
                                )
                              }
                              disabled={chatLoading || !canChat}
                              className="rounded-md border border-cyan-300/60 bg-transparent px-3 py-1.5 font-semibold text-cyan-100 disabled:cursor-not-allowed disabled:opacity-60"
                            >
                              Deep Visual Guess
                            </button>
                            <button
                              type="button"
                              onClick={() =>
                                handleFallbackChatPrompt(
                                  "Return a structured extraction using this exact format:\nProduct name: ...\nForm factor: ...\nQuantity: ...\nEquipment/components detected: ...\nIf a field is uncertain, write 'Unclear'."
                                )
                              }
                              disabled={chatLoading || !canChat}
                              className="rounded-md border border-emerald-300/60 bg-emerald-900/20 px-3 py-1.5 font-semibold text-emerald-100 disabled:cursor-not-allowed disabled:opacity-60"
                            >
                              Structured Extract
                            </button>
                          </div>
                        </div>
                      </div>
                    ) : null}
                    {result.description ? (
                      <div className="rounded-lg bg-slate-800/60 p-3">
                        <h4 className="mb-1 text-sm font-bold text-cyan-200">Image Description</h4>
                        <p className="text-sm text-cyan-50">{result.description}</p>
                      </div>
                    ) : null}
                    {result.extractedText ? (
                      <div className="rounded-lg bg-slate-800/60 p-3">
                        <h4 className="mb-1 text-sm font-bold text-cyan-200">Extracted Text</h4>
                        <p className="text-sm text-cyan-50">{result.extractedText}</p>
                      </div>
                    ) : null}
                    <div className={`text-sm leading-6 ${result.source === "fallback+ocr" ? "rounded-lg border border-amber-300/30 bg-amber-950/20 p-3 text-amber-50" : "text-cyan-50"}`}>
                      {result.source === "fallback+ocr" && (
                        <p className="mb-2 font-semibold text-amber-100">🔍 OCR-Generated Summary:</p>
                      )}
                      <p>{result.summary}</p>
                    </div>
                    <div className="mt-4 border-t border-cyan-300/20 pt-4">
                      <h4 className="mb-2 text-sm font-bold text-cyan-200">Markdown Export</h4>
                      <pre className="overflow-x-auto rounded bg-slate-850 p-2 text-xs text-emerald-200">
                        {result.markdownSummary}
                      </pre>
                    </div>
                  </div>
                )}

                {activeTab === "keypoints" && (
                  <div className="space-y-2">
                    <h3 className="text-lg font-bold text-cyan-100">Key Points</h3>
                    {result.keyPoints.length === 0 ? (
                      <p className="text-sm text-cyan-300">No key points available.</p>
                    ) : (
                      result.keyPoints.map((point, idx) => (
                        <div key={idx} className="rounded-lg bg-slate-800/50 p-3">
                          <p className="text-sm text-cyan-50">{point}</p>
                        </div>
                      ))
                    )}
                  </div>
                )}

                {activeTab === "mindmap" && (
                  <div>
                    <h3 className="mb-3 text-lg font-bold text-cyan-100">Mind Map</h3>
                    <MindMap title={result.title} keyPoints={result.keyPoints} />
                  </div>
                )}

                {activeTab === "chat" && (
                  <div>
                    <ChatAI messages={messages} onAsk={handleAsk} disabled={!canChat} loading={chatLoading} />
                  </div>
                )}
              </div>
            </div>
          </div>
        ) : null}

        {hasSummary ? (
          <div className="rounded-3xl bg-slate-900/80 p-5 ring-1 ring-cyan-300/20">
            <History items={history} onLoad={loadHistoryItem} onDelete={removeHistory} />
          </div>
        ) : null}
      </div>
    </main>
  );
}

export default Home;
